    public void executeSqlQuery() throws IOException, SQLException {
        try (BufferedReader reader = new BufferedReader(new FileReader(sqlQueryFilePath));
             BufferedWriter writer = new BufferedWriter(new FileWriter(outputFilePath, true))) { // Append to the file

